const ELEMENT_PROP_KEYS = new Set(["theme","text","highlightWord","scroll","dotSize","accent","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  text: "remocn is live",
  highlightWord: "live",
  scroll: 54,
  dotSize: 0.45,
  accent: "#3B5BFD",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type LedTickerElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof LedTickerBase>;

const LedTickerInner = forwardRef<
  HTMLDivElement,
  LedTickerElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<LedTicker>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <LedTickerBase
          {...(componentProps as unknown as ComponentProps<typeof LedTickerBase>)}
        />
      </div>
    </Sequence>
  );
});

export const LedTicker = Interactive.withSchema({
  Component: LedTickerInner,
  componentName: "<LedTicker>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
